const inputData = $input.first().json;
const tenantId = inputData.tenant_id;
const actorType = inputData.actor_type || 'system';
const actorId = inputData.actor_id || null;
const action = inputData.action || 'core.audit_test';
const entityType = inputData.entity_type || 'system_test';
const entityId = inputData.entity_id || null;
const metadata = inputData.metadata || { is_test: true, triggered_by: 'n8n_core_test' };

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const validActors = ['user', 'agent', 'system'];

if (tenantId && !uuidRegex.test(String(tenantId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_TENANT_ID",
      message: "O parâmetro 'tenant_id', se fornecido, deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!validActors.includes(actorType)) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_ACTOR_TYPE",
      message: `actor_type deve ser um dos seguintes: ${validActors.join(', ')}`,
      timestamp: new Date().toISOString()
    }
  }];
}

if (!action || typeof action !== 'string' || action.trim().length === 0) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_ACTION",
      message: "O parâmetro 'action' é obrigatório (ex: 'user.login', 'test.executed')",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: tenantId ? String(tenantId).trim() : null,
    actor_type: actorType,
    actor_id: actorId && uuidRegex.test(String(actorId).trim()) ? String(actorId).trim() : null,
    action: String(action).trim(),
    entity_type: entityType ? String(entityType).trim() : null,
    entity_id: entityId && uuidRegex.test(String(entityId).trim()) ? String(entityId).trim() : null,
    metadata: JSON.stringify(typeof metadata === 'object' ? metadata : { raw: metadata })
  }
}];

const items = $input.all();
const first = items[0];

if (first.error) {
  return [{
    json: {
      status: "error",
      code: "DB_INSERT_ERROR",
      message: "Erro ao gravar log de auditoria no PostgreSQL",
      error_details: first.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

const log = first.json;
return [{
  json: {
    status: "success",
    code: "AUDIT_LOG_CREATED",
    message: "Evento de auditoria registrado com sucesso no PostgreSQL",
    data: {
      audit_log_id: log.audit_log_id,
      tenant_id: log.tenant_id || null,
      actor_type: log.actor_type,
      actor_id: log.actor_id || null,
      action: log.action,
      entity_type: log.entity_type || null,
      entity_id: log.entity_id || null,
      metadata: log.metadata,
      created_at: log.created_at
    },
    timestamp: new Date().toISOString()
  }
}];
